    c: '#include <stdint.h>\n#include <stdlib.h>\ntypedef struct LRUCache{int c,n;int32_t k[3001],v[3001];}LRUCache;LRUCache*lruCacheCreate(int32_t c){LRUCache*s=calloc(1,sizeof(*s));s->c=c;return s;}int find(LRUCache*s,int k){for(int i=0;i<s->n;i++)if(s->k[i]==k)return i;return-1;}void touch(LRUCache*s,int i){int k=s->k[i],v=s->v[i];for(;i+1<s->n;i++){s->k[i]=s->k[i+1];s->v[i]=s->v[i+1];}s->k[s->n-1]=k;s->v[s->n-1]=v;}int32_t lruCacheGet(LRUCache*s,int32_t k){int i=find(s,k);if(i<0)return-1;int v=s->v[i];touch(s,i);return v;}void lruCachePut(LRUCache*s,int32_t k,int32_t v){int i=find(s,k);if(i>=0){s->v[i]=v;touch(s,i);return;}if(s->n==s->c){for(i=0;i+1<s->n;i++){s->k[i]=s->k[i+1];s->v[i]=s->v[i+1];}s->n--;}s->k[s->n]=k;s->v[s->n++]=v;}void lruCacheFree(LRUCache*s){free(s);}',
